import{bV as l,aL as a,u as n,G as e}from"./chunks/framework.CzwWnRE6.js";const u="/linux/xshell.png",r="/linux/%E5%BF%AB%E7%85%A7.jpg",L=JSON.parse('{"title":"初识Linux","description":"","frontmatter":{"title":"初识Linux","date":"2026/01/07 13:40:53","permalink":"/linux/","sidebarSort":1,"categories":["linux"]},"headers":[],"relativePath":"linux/初识Linux.md","filePath":"linux/初识Linux.md","lastUpdated":null}'),t={name:"linux/初识Linux.md"};function o(x,i,h,s,d,p){return a(),n("div",null,[...i[0]||(i[0]=[e('<h1 id="初识linux" tabindex="-1">初识Linux <a class="header-anchor" href="#初识linux" aria-label="Permalink to &quot;初识Linux&quot;">​</a></h1><h2 id="操作系统概述" tabindex="-1">操作系统概述 <a class="header-anchor" href="#操作系统概述" aria-label="Permalink to &quot;操作系统概述&quot;">​</a></h2><p>我们所熟知的计算机是由：硬件和软件所组成。</p><p><strong>硬件：</strong> 计算机系统中由电子，机械和光电元件等组成的各种物理装置的总称。</p><p><strong>软件：</strong> 是用户和计算机硬件之间的接口和桥梁，用户通过软件与计算机进行交流。</p><p>而操作系统，就是软件的一类。</p><p><strong>操作系统的作用：</strong></p><ol><li>管理计算机硬件资源</li><li>提供用户和计算机硬件之间的接口</li><li>控制计算机的运行</li></ol><h3 id="常见的操作系统" tabindex="-1">常见的操作系统 <a class="header-anchor" href="#常见的操作系统" aria-label="Permalink to &quot;常见的操作系统&quot;">​</a></h3><ol><li>Windows</li><li>macOS</li><li>Linux</li><li>Android</li><li>iOS</li></ol><h2 id="初识-linux" tabindex="-1">初识 Linux <a class="header-anchor" href="#初识-linux" aria-label="Permalink to &quot;初识 Linux&quot;">​</a></h2><p>Linux 由林纳斯·托瓦兹（Linus Torvalds）在 1991 年创建，是一种自由和开放源代码的操作系统。</p><h3 id="了解-linux" tabindex="-1">了解 Linux <a class="header-anchor" href="#了解-linux" aria-label="Permalink to &quot;了解 Linux&quot;">​</a></h3><ul><li>Linux 是一种自由和开放源代码的操作系统，它的主要作用是管理计算机的资源和提供用户界面。</li><li>Linux 的一个特点是用户友好，操作简单。</li><li>Linux 的另一个特点是自由和开放源代码，这意味着用户可以自由地使用、修改和分发 Linux 操作系统的源代码。</li></ul><h3 id="linux-内核" tabindex="-1">Linux 内核 <a class="header-anchor" href="#linux-内核" aria-label="Permalink to &quot;Linux 内核&quot;">​</a></h3><p>Linux 系统组成部分：</p><ul><li>内核：Linux 内核是操作系统的核心，负责管理计算机的硬件资源和提供用户界面。</li><li>应用程序：Linux 应用程序是用户使用 Linux 操作系统的工具和程序。</li><li>库：Linux 库是应用程序运行所需的代码和数据。</li><li>工具：Linux 工具是用于管理和配置 Linux 操作系统的程序。</li></ul><h3 id="常见的-linux-发行版" tabindex="-1">常见的 Linux 发行版 <a class="header-anchor" href="#常见的-linux-发行版" aria-label="Permalink to &quot;常见的 Linux 发行版&quot;">​</a></h3><ul><li>Ubuntu</li><li>Debian</li><li>Fedora</li><li>CentOS</li><li>Arch Linux</li></ul><h2 id="虚拟机" tabindex="-1">虚拟机 <a class="header-anchor" href="#虚拟机" aria-label="Permalink to &quot;虚拟机&quot;">​</a></h2><p>虚拟机是一种软件，借助虚拟化技术，在一台物理计算机上模拟出多台虚拟机，每个虚拟机都可以运行一个独立的操作系统。</p><p>这里使用的是 VMware Workstation 虚拟机软件。</p><ul><li>安装 VMware Workstation</li><li>安装 Linux 发行版</li></ul><h2 id="连接-linux" tabindex="-1">连接 Linux <a class="header-anchor" href="#连接-linux" aria-label="Permalink to &quot;连接 Linux&quot;">​</a></h2><p>操作系统的使用形式：</p><ul><li>命令行界面（CLI）：使用操作系统提供的各类命令，以获得字符反馈的形式去使用操作系统；</li><li>图形用户界面（GUI）：使用操作系统提供的可视化界面，以鼠标和键盘等输入设备去操作操作系统。</li></ul><p>在使用 Linux 操作系统，多数使用的是命令行界面（CLI）。</p><p>这是因为：</p><ul><li>Linux 从诞生至今，在图形化页面的优化上，并未重点发力。所以 Linux 操作系统的图形化页面：不好用、不稳定。</li><li>在开发中，使用命令行形式，效率更高，更加直观，并且资源占用低，程序运行更稳定。</li></ul><h3 id="xshell" tabindex="-1">Xshell <a class="header-anchor" href="#xshell" aria-label="Permalink to &quot;Xshell&quot;">​</a></h3><p>我们使用 VMware 可以得到 Linux 虚拟机，但是在 VMware 中操作 Linux 的命令行页面不太方便，主要是：</p><ul><li>内容的复制、粘贴跨越 VMware 不方便</li><li>文件的上传、下载跨越 VMware 不方便</li><li>也就是和 Linux 系统的各类交互，跨越 VMware 不方便</li></ul><p>我们可以通过第三方软件，Xshell，远程连接到 Linux 操作系统之上。并通过 Xshell 去操作 Linux 系统。这样各类操作都会十分的方便。</p><p>Xshell 是一个基于 SSH 协议的远程登录工具，它可以在 Windows、macOS 和 Linux 等操作系统上运行。</p><p>打开虚拟机，输入 ipconfig 命令，查看虚拟机的 IP 地址。</p><p><img src="'+u+'" alt="xshell"></p><h2 id="虚拟机快照" tabindex="-1">虚拟机快照 <a class="header-anchor" href="#虚拟机快照" aria-label="Permalink to &quot;虚拟机快照&quot;">​</a></h2><p>虚拟机快照是指在虚拟机运行时，对虚拟机的状态进行保存。</p><h3 id="作用" tabindex="-1">作用 <a class="header-anchor" href="#作用" aria-label="Permalink to &quot;作用&quot;">​</a></h3><ul><li>可以保存虚拟机的当前状态，以便在需要时恢复到该状态。</li><li>可以在虚拟机运行时，对虚拟机的状态进行备份，防止数据丢失。</li></ul><h3 id="操作" tabindex="-1">操作 <a class="header-anchor" href="#操作" aria-label="Permalink to &quot;操作&quot;">​</a></h3><p><img src="'+r+'" alt="快照"></p>',42)])])}const b=l(t,[["render",o]]);export{L as __pageData,b as default};
